import { describe, expect, it } from 'vitest';
import report from '../../../data/quality-report.json';
import { QUALITY_REPORT_VERSION } from '../../../src/application/qualityReport';

/**
 * The app loads data/quality-report.json at startup. It is generated by `npm run build-quality-report`,
 * so these tests catch a report that has fallen out of step with the code.
 */
describe('committed quality report', () => {
  it('matches the current report version', () => {
    expect(report.version).toBe(QUALITY_REPORT_VERSION);
  });

  it('covers the full sample: 40 minute files and 40 daily files', () => {
    expect(report.files).toEqual({ intraday: 40, daily: 40 });
    expect(report.totalRows).toBe(5_325_341); // 5,295,239 minute + 30,102 daily rows, per sample-data/files.csv
  });
});
